import pandas as pd

def solve(data):
     df = pd.DataFrame(data['rows'], columns=['order','city','amount'])
     mask = (df['city'] == data['city']) & (df['amount'] >= data['minimum'])
     return df.loc[mask, 'order'].tolist()
